<script setup>
import { onMounted, ref, watch } from "vue";
import UiIcon from "../../components/UiIcon.vue";
import { createAdminActivity, getAdminActivities, updateAdminActivityStatus } from "../../services/adminRepository";
const items=ref([]),total=ref(0),page=ref(1),query=ref(""),status=ref(""),loading=ref(true),error=ref(""),show=ref(false),saving=ref(false),toast=ref(""); const form=ref({title:"",summary:"",content:"",category:"campus",location:"",registration_deadline:"",starts_at:"",ends_at:"",capacity:null,status:"draft"}); const statusLabel={draft:"草稿",published:"报名中",closed:"已结束",archived:"已归档"}; const cat={campus:"校园活动",academic:"学术交流",volunteer:"志愿服务",competition:"竞赛",lecture:"讲座",sports:"体育"};
async function load(){loading.value=true;try{const r=await getAdminActivities({page:page.value,query:query.value||undefined,status:status.value||undefined});items.value=r.items;total.value=r.total}catch(e){error.value=e.response?.data?.message||e.message||"活动加载失败"}finally{loading.value=false}} async function submit(){saving.value=true;try{await createAdminActivity({...form.value,capacity:form.value.capacity?Number(form.value.capacity):null});show.value=false;toast.value="活动已保存";await load()}catch(e){toast.value=e.response?.data?.message||"活动保存失败"}finally{saving.value=false}} async function change(item,next){try{await updateAdminActivityStatus(item.id,next);toast.value=next==="published"?"活动已发布":"活动已结束";await load()}catch(e){toast.value=e.response?.data?.message||"状态更新失败"}} let timer;watch([query,status],()=>{page.value=1;clearTimeout(timer);timer=setTimeout(load,260)});onMounted(load);
</script>
<template><main class="portal-page admin-portal page-enter"><div v-if="toast" class="portal-toast" role="status">{{ toast }}</div><div class="portal-heading"><div><span class="portal-kicker">校园活动</span><h1>活动管理</h1><p>草稿、发布和结束均通过管理员接口写入真实数据库。</p></div><button class="primary-button" @click="show=true"><UiIcon name="PhPlus" />创建活动</button></div><section class="portal-toolbar"><div class="portal-search"><UiIcon name="PhMagnifyingGlass" /><input v-model="query" placeholder="搜索活动名称或地点" /></div><select v-model="status"><option value="">全部状态</option><option value="draft">草稿</option><option value="published">报名中</option><option value="closed">已结束</option></select><span>{{ total }} 项活动</span></section><div v-if="loading" class="portal-loading"><i v-for="n in 4" :key="n"></i></div><div v-else-if="error" class="portal-error"><strong>{{ error }}</strong><button class="secondary-button" @click="load">重试</button></div><section v-else class="activity-manage-grid"><article v-for="item in items" :key="item.id" class="activity-manage-card"><div class="activity-card-top"><span>{{ cat[item.category] }}</span><em :class="`status-${item.status}`">{{ statusLabel[item.status] }}</em></div><h2>{{ item.title }}</h2><p>{{ item.summary||item.content }}</p><dl><div><UiIcon name="PhMapPin" /><dd>{{ item.location||"地点待定" }}</dd></div><div><UiIcon name="PhClock" /><dd>{{ item.starts_at?new Date(item.starts_at).toLocaleString("zh-CN"):"时间待定" }}</dd></div></dl><footer><span>容量 {{ item.capacity||"不限" }}</span><button v-if="item.status==='draft'" @click="change(item,'published')">发布 <UiIcon name="PhArrowRight" /></button><button v-else-if="item.status==='published'" @click="change(item,'closed')">结束 <UiIcon name="PhArrowRight" /></button></footer></article><div v-if="!items.length" class="portal-empty">暂无活动记录</div></section><div class="tch-pagination"><button :disabled="page<=1" @click="page--;load()">上一页</button><span>{{ page }} / {{ Math.max(1,Math.ceil(total/20)) }}</span><button :disabled="page>=Math.ceil(total/20)" @click="page++;load()">下一页</button></div><div v-if="show" class="portal-overlay"><form class="portal-drawer" @submit.prevent="submit"><div class="drawer-head"><div><span>创建活动</span><h2>发布校园活动</h2></div><button type="button" class="icon-button" @click="show=false"><UiIcon name="PhX" /></button></div><label>活动名称<input v-model="form.title" required /></label><label>摘要<textarea v-model="form.summary" maxlength="500" /></label><label>活动内容<textarea v-model="form.content" required /></label><div class="form-pair"><label>类别<select v-model="form.category"><option v-for="(label,key) in cat" :key="key" :value="key">{{ label }}</option></select></label><label>容量<input v-model="form.capacity" type="number" min="1" /></label></div><label>地点<input v-model="form.location" /></label><div class="form-pair"><label>开始时间<input v-model="form.starts_at" type="datetime-local" /></label><label>报名截止<input v-model="form.registration_deadline" type="datetime-local" /></label></div><div class="drawer-actions"><button type="button" class="secondary-button" @click="show=false">取消</button><button class="primary-button" :disabled="saving">{{ saving?"保存中…":"保存草稿" }}</button></div></form></div></main></template>
